BEGIN;
SET LOCAL standard_conforming_strings = on;
CREATE TABLE IF NOT EXISTS textbook_vocabulary (
  id varchar(21) PRIMARY KEY,
  book_id varchar(32) NOT NULL,
  global_order integer NOT NULL CHECK (global_order > 0),
  unit_number integer NOT NULL CHECK (unit_number BETWEEN 1 AND 6),
  order_in_unit integer NOT NULL CHECK (order_in_unit > 0),
  english varchar(64) NOT NULL,
  meaning_zh text NOT NULL,
  usage_note text,
  lesson_page integer NOT NULL,
  source_pdf_page integer NOT NULL,
  source_printed_page integer NOT NULL,
  source_image_url text NOT NULL,
  source_image_sha256 char(64) NOT NULL,
  metadata json NOT NULL,
  UNIQUE (book_id, unit_number, order_in_unit)
);
ON CONFLICT (id) DO UPDATE SET "book_id" = EXCLUDED."book_id", "global_order" = EXCLUDED."global_order", "unit_number" = EXCLUDED."unit_number", "order_in_unit" = EXCLUDED."order_in_unit", "english" = EXCLUDED."english", "meaning_zh" = EXCLUDED."meaning_zh", "usage_note" = EXCLUDED."usage_note", "lesson_page" = EXCLUDED."lesson_page", "source_pdf_page" = EXCLUDED."source_pdf_page", "source_printed_page" = EXCLUDED."source_printed_page", "source_image_url" = EXCLUDED."source_image_url", "source_image_sha256" = EXCLUDED."source_image_sha256", "metadata" = EXCLUDED."metadata";
COMMIT;
